/*!
 * A query result. Must be freed with duckdb_destroy_result.
 *
 * history:
 * - stable: v0.1.0
 */
struct duckdb_result {
	idx_t deprecated_column_count;
	idx_t deprecated_row_count;
	idx_t deprecated_rows_changed;
	duckdb_column *deprecated_columns;
	char *deprecated_error_message;
	void *internal_data;
};

duckdb_state duckdb_query(duckdb_connection connection, const char *query, duckdb_result *out) {
	Connection *conn = reinterpret_cast<Connection *>(connection);
	try {
		auto result = conn->Query(query);
		return DuckDBTranslateResult(std::move(result), out);
	} catch (...) {
		return DuckDBError;
	}
}

duckdb_state DuckDBTranslateResult(unique_ptr<QueryResult> result_p, duckdb_result *out) {
	auto &result = *result_p;
	D_ASSERT(result_p);
	if (!out) {
		// no result to write to, only return the status
		return !result.HasError() ? DuckDBSuccess : DuckDBError;
	}

	memset(out, 0, sizeof(duckdb_result));

	// initialize the result_data object
	auto result_data = new DuckDBResultData();
	result_data->result = std::move(result_p);
	result_data->result_set_type = CAPIResultSetType::CAPI_RESULT_TYPE_NONE;
	out->internal_data = result_data;

	if (result.HasError()) {
		// write the error message
		out->deprecated_error_message = (char *)result.GetError().c_str(); // NOLINT
		return DuckDBError;
	}
	// copy the data
	// first write the metadata
	out->deprecated_column_count = result.ColumnCount();
	out->deprecated_rows_changed = 0;
	return DuckDBSuccess;
}

void duckdb_destroy_result(duckdb_result *result) {
	if (result->deprecated_columns) {
		for (idx_t i = 0; i < result->deprecated_column_count; i++) {
			DuckdbDestroyColumn(result->deprecated_columns[i], result->deprecated_row_count);
		}
		duckdb_free(result->deprecated_columns);
	}
	if (result->internal_data) {
		auto result_data = reinterpret_cast<duckdb::DuckDBResultData *>(result->internal_data);
		delete result_data;
	}
	memset(result, 0, sizeof(duckdb_result));
}

const char *duckdb_result_error(duckdb_result *result) {
	if (!result || !result->internal_data) {
		return nullptr;
	}
	auto &result_data = *(reinterpret_cast<duckdb::DuckDBResultData *>(result->internal_data));
	return !result_data.HasError() ? nullptr : result_data.GetError().c_str();
}

duckdb_error_type duckdb_result_error_type(duckdb_result *result) {
	if (!result || !result->internal_data) {
		return DUCKDB_ERROR_INVALID;
	}
	auto &result_data = *(reinterpret_cast<duckdb::DuckDBResultData *>(result->internal_data));
	if (!result_data.HasError()) {
		return DUCKDB_ERROR_INVALID;
	}
	return duckdb::ErrorTypeToC(result_data.GetErrorType());

//! Either a query handle or a stream opened from one. Only the streaming entry points care which;
//! everything else reads the metadata and the error, which both carry
struct DuckDBResultData {
	//! The query handle, or null once a stream was opened from it
	unique_ptr<QueryResult> result;
	//! The stream opened from the handle (may be null)
	unique_ptr<QueryResultStream<>> stream;
	// Results can only use either the new API or the old API, not a mix of the two
	// They start off as "none" and switch to one or the other when an API method is used
	CAPIResultSetType result_set_type;

	bool IsStreaming() const {
		return stream != nullptr;
	}
	//! The retained result. Only valid when the result is not streaming
	QueryResult &Retained() const {
		D_ASSERT(result);
		return *result;
	}
	bool HasError() const {
		return stream ? stream->HasError() : result->HasError();
	}
	const string &GetError() const {
		return stream ? stream->GetError() : result->GetError();
	}
	const ExceptionType &GetErrorType() const {
		return stream ? stream->GetErrorType() : result->GetErrorType();
	}
	idx_t ColumnCount() const {
		return stream ? stream->ColumnCount() : result->ColumnCount();
	}
	const vector<LogicalType> &GetTypes() const {
		return stream ? stream->GetTypes() : result->GetTypes();
	}
	const Identifier &ColumnName(idx_t index) const {
		return stream ? stream->ColumnName(index) : result->ColumnName(index);
	}
	StatementType GetStatementType() const {
		return stream ? stream->GetStatementType() : result->GetStatementType();
	}
	const StatementProperties &GetStatementProperties() const {
		return stream ? stream->GetStatementProperties() : result->GetStatementProperties();
	}
	ClientProperties &GetClientProperties() {
		return stream ? stream->GetClientProperties() : result->client_properties;
	}
	unique_ptr<DataChunk> Fetch() {
		return stream ? stream->Fetch() : result->Fetch();
	}
};

